import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';

const url = process.argv[2] || 'http://localhost:8901/index.html';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });

const errors = [];
const warnings = [];
page.on('console', (msg) => {
  if (msg.type() === 'error') errors.push(msg.text());
  else if (msg.type() === 'warning') warnings.push(msg.text());
});
page.on('pageerror', (err) => errors.push('PAGEERROR: ' + err.message + '\n' + (err.stack || '').split('\n').slice(0, 4).join('\n')));
page.on('requestfailed', (req) => errors.push('REQFAIL: ' + req.url() + ' ' + (req.failure()?.errorText || '')));

await page.goto(url, { waitUntil: 'networkidle' });
await page.waitForTimeout(2500);

const state = await page.evaluate(() => {
  const active = document.querySelector('.screen.is-active');
  return {
    activeScreen: active ? active.id : null,
    hasApp: !!document.getElementById('app'),
  };
});

await page.screenshot({ path: '/tmp/opencode/shot-title.jpg', quality: 70, type: 'jpeg' });
console.log(JSON.stringify({ state, errors: errors.slice(0, 40), warnings: warnings.slice(0, 10) }, null, 2));
await browser.close();

