436: function statBars(stats, compare = null) {
437:   const max = Math.max(18, ...Object.values(stats), ...(compare ? Object.values(compare) : []));
438:   return `<div class="stat-block">${STAT_KEYS.map((key) => {
439:     const value = stats[key] || 0;
440:     const pct = clamp((value / max) * 100, 4, 100);
441:     const delta = compare ? value - (compare[key] || 0) : 0;
442:     return `<div class="stat-line">
443:       <span>${STAT_LABELS[key]}${delta ? ` <em style="color:${delta > 0 ? 'var(--teal)' : 'var(--rose)'};font-style:normal">${delta > 0 ? '+' : ''}${delta}</em>` : ''}</span>
444:       <div class="stat-track"><i class="${value >= 14 ? 'high' : ''}" style="width:${pct}%"></i></div>
445:       <b>${value}</b>
446:     </div>`;
447:   }).join('')}</div>`;
448: }
