567: export function drawMinimap(canvas, dungeon, view, party) {
568:   if (!canvas) return;
569:   const ctx = canvas.getContext('2d');
570:   const w = canvas.width;
571:   const h = canvas.height;
572:   const theme = dungeon.theme;
573:   ctx.clearRect(0, 0, w, h);
574:   ctx.fillStyle = 'rgba(7,6,11,0.82)';
575:   ctx.fillRect(0, 0, w, h);
576:   const sx = w / dungeon.width;
577:   const sy = h / dungeon.height;
578:   const size = Math.min(sx, sy);
579:   const ox = (w - dungeon.width * size) / 2;
580:   const oy = (h - dungeon.height * size) / 2;
581: 
582:   for (let y = 0; y < dungeon.height; y += 1) {
583:     for (let x = 0; x < dungeon.width; x += 1) {
584:       const key = `${x},${y}`;
585:       if (!view.explored.has(key)) continue;
586:       const isFloor = tileAt(dungeon, x, y) === 1;
587:       ctx.fillStyle = isFloor ? (view.visible.has(key) ? theme.wallTop : 'rgba(70,60,80,0.35)') : 'rgba(20,16,26,0.5)';
588:       ctx.fillRect(ox + x * size, oy + y * size, Math.ceil(size), Math.ceil(size));
589:     }
