600:     if (e.cleared) continue;
601:     if (!view.explored.has(`${e.x},${e.y}`)) continue;
602:     dot(e.x, e.y, e.encounterType === 'boss' ? '#ffd479' : '#f07d8b', Math.max(1.6, size * 0.28));
603:   }
