211:   nextTurn() {
212:     if (this.finished) return;
213:     if (this.checkEnd()) return;
214:     if (!this.queue.length) {
215:       this.round += 1;
216:       this.buildQueue();
217:       this.addLog(`<b>라운드 ${this.round}</b>`, 'system');
218:       this.cb.onFx?.({ type: 'round', round: this.round });
219:       this.cb.onUpdate?.();
220:     }
221:     const uid = this.queue.shift();
222:     const unit = this.getUnit(uid);
223:     if (!unit || !unit.alive) {
224:       setTimeout(() => this.nextTurn(), 60);
225:       return;
226:     }
227:     this.activeUid = uid;
228:     this.pendingAction = null;
229:     this.startOfTurn(unit);
230:     if (this.finished) return;
231:     if (!unit.alive) {
232:       this.finishTurn(unit);
233:       return;
234:     }
235:     const stunned = this.hasStatus(unit, 'stun');
236:     if (stunned) {
237:       this.phase = 'resolving';
238:       this.setMessage(`${unit.name}은(는) 기절해 행동하지 못합니다.`);
239:       this.addLog(`<span class="${unit.side}">${unit.name}</span> 기절`, 'control');
240:       this.cb.onFx?.({ type: 'status', uid: unit.uid, text: '기절' });
241:       this.cb.onUpdate?.();
242:       setTimeout(() => this.finishTurn(unit), 720);
243:       return;
244:     }
245:     if (unit.side === 'ally') {
246:       this.phase = 'select';
247:       this.setMessage(`${unit.name}의 턴입니다.`);
248:       this.cb.onUpdate?.();
249:       if (this.auto) setTimeout(() => this.autoAlly(unit), 420);
250:     } else {
251:       this.phase = 'enemy';
252:       this.setMessage(`${unit.name}이(가) 노리고 있습니다.`);
253:       this.cb.onUpdate?.();
254:       setTimeout(() => this.enemyTurn(unit), 520);
255:     }
256:   }
257: 
258:   startOfTurn(unit) {
259:     // Cooldowns tick down at the start of the unit's own turn.
260:     for (const key of Object.keys(unit.cooldowns)) {
261:       unit.cooldowns[key] = Math.max(0, unit.cooldowns[key] - 1);
262:     }
263:     if (unit.trait === 'tidal_grace') {
264:       const heal = Math.round(unit.maxHp * 0.03);
265:       this.healUnit(unit, heal, null, '조수의 은총');
266:     }
267:     for (const status of [...unit.statuses]) {
268:       if (status.id === 'poison' || status.id === 'burn') {
269:         const amount = Math.max(1, Math.round(unit.maxHp * status.value));
270:         this.applyRawDamage(unit, amount, status.id === 'burn' ? '화상' : '독');
271:       } else if (status.id === 'regen') {
272:         const amount = Math.max(1, Math.round(unit.maxHp * status.value));
273:         this.healUnit(unit, amount, null, '재생');
274:       }
275:     }
276:     if (!unit.alive) return;
277:     if (unit.trait === 'deathless' && unit.hp <= 0) unit.hp = 1;
278:   }
279: 
280:   finishTurn(unit) {
281:     if (this.finished) return;
282:     if (unit?.alive) {
283:       for (const status of [...unit.statuses]) {
284:         status.turns -= 1;
285:         if (status.turns <= 0) {
286:           unit.statuses = unit.statuses.filter((s) => s !== status);
287:         }
288:       }
289:     }
290:     this.activeUid = null;
291:     this.pendingAction = null;
292:     this.cb.onUpdate?.();
293:     if (this.checkEnd()) return;
294:     setTimeout(() => this.nextTurn(), 230);
295:   }
296: 
297:   checkEnd() {
298:     if (this.finished) return true;
299:     const alliesAlive = this.getAlive('ally').length;
300:     const enemiesAlive = this.getAlive('enemy').length;
301:     if (enemiesAlive === 0) {
302:       this.finish('victory');
303:       return true;
304:     }
305:     if (alliesAlive === 0) {
306:       this.finish('defeat');
307:       return true;
308:     }
309:     return false;
310:   }
311: 
312:   finish(result) {
313:     if (this.finished) return;
314:     this.finished = true;
315:     this.phase = result;
316:     const enemies = this.units.filter((u) => u.side === 'enemy');
317:     const boss = enemies.some((u) => u.boss);
318:     const baseXp = enemies.reduce((sum, u) => sum + (u.boss ? 120 : 28 + this.floor * 6), 0);
319:     const xp = Math.round(baseXp * (result === 'victory' ? 1 : 0.25));
320:     const gold = Math.round(enemies.reduce((sum, u) => sum + (u.boss ? 120 : 12 + this.floor * 4), 0) * (result === 'victory' ? 1 : 0.3)) + this.stolenGold;
321:     const potionDrop = result === 'victory' && Math.random() < (boss ? 0.85 : 0.28) ? 1 : 0;
322:     const etherDrop = result === 'victory' && Math.random() < (boss ? 0.65 : 0.18) ? 1 : 0;
323:     this.result = {
324:       result,
325:       xp,
326:       gold,
327:       potions: potionDrop,
328:       ethers: etherDrop,
329:       boss,
330:       floor: this.floor,
331:       round: this.round,
332:       units: this.units.map((u) => ({ uid: u.uid, side: u.side, hp: u.hp, maxHp: u.maxHp, aether: u.aether, maxAether: u.maxAether, alive: u.alive }))
333:     };
334:     if (result === 'victory') {
335:       this.addLog('<b>전투 승리.</b>', 'system');
336:       this.setMessage('승리했습니다.');
337:       this.cb.onFx?.({ type: 'victory' });
338:       setTimeout(() => this.cb.onEnd?.(this.result), 900);
339:     } else {
340:       this.addLog('<b>원정대가 쓰러졌습니다.</b>', 'system');
341:       this.setMessage('패배...');
342:       this.cb.onFx?.({ type: 'defeat' });
343:       setTimeout(() => this.cb.onEnd?.(this.result), 1100);
344:     }
345:     this.cb.onUpdate?.();
346:   }
