353:     const unit = this.getActive();
354:     if (!unit || unit.side !== 'ally' || this.phase !== 'select') return [];
355:     const ability = unit.ability;
356:     const kitAbility = unit.kitAbility;
357:     const actions = [
358:       {
359:         id: 'basic',
360:         name: '공격',
361:         icon: '⚔',
362:         cost: 0,
363:         cooldown: 0,
364:         target: 'enemy',
365:         kind: unit.attackKind,
366:         power: 1,
367:         reach: unit.attackReach,
368:         desc: unit.attackKind === 'physical' ? '무기로 적을 공격합니다.' : '마법으로 적을 공격합니다.',
369:         disabled: false,
370:         key: '1'
371:       }
372:     ];
373:     if (ability) {
374:       const cd = unit.cooldowns[ability.id] || 0;
375:       actions.push({
376:         ...ability,
377:         id: ability.id,
378:         icon: '✦',
379:         name: ability.name,
380:         desc: ability.desc,
381:         cost: this.costFor(unit, ability),
382:         disabled: cd > 0 || unit.aether < this.costFor(unit, ability),
383:         reason: cd > 0 ? `재사용 ${cd}턴` : unit.aether < this.costFor(unit, ability) ? '에테르 부족' : '',
384:         key: '2'
385:       });
386:     }
387:     if (kitAbility && kitAbility.id) {
388:       const cd = unit.cooldowns[kitAbility.id] || 0;
389:       actions.push({
390:         ...kitAbility,
391:         id: kitAbility.id,
392:         icon: '◆',
393:         name: kitAbility.name,
394:         desc: kitAbility.desc,
395:         cost: this.costFor(unit, kitAbility),
396:         disabled: cd > 0 || unit.aether < this.costFor(unit, kitAbility),
397:         reason: cd > 0 ? `재사용 ${cd}턴` : unit.aether < this.costFor(unit, kitAbility) ? '에테르 부족' : '',
398:         key: '3'
399:       });
400:     }
401:     actions.push({
402:       id: 'defend',
403:       name: '방어',
404:       icon: '◈',
405:       cost: 0,
406:       cooldown: 0,
407:       target: 'self',
408:       kind: 'buff',
409:       desc: '이번 턴 받는 피해를 40% 줄이고 에테르를 10% 회복합니다.',
410:       disabled: false,
411:       key: '4'
412:     });
413:     actions.push({
414:       id: 'potion',
415:       name: '회복약',
416:       icon: '✚',
417:       cost: 0,
418:       cooldown: 0,
419:       target: 'ally',
420:       kind: 'heal',
421:       power: 0.35,
422:       desc: `아군 하나의 생명력을 35% 회복합니다. 남은 수: ${this.items.potions}`,
423:       disabled: this.items.potions <= 0,
424:       reason: this.items.potions <= 0 ? '회복약 없음' : '',
425:       key: '5',
426:       item: true
427:     });
428:     actions.push({
429:       id: 'ether',
430:       name: '에테르약',
431:       icon: '✦',
432:       cost: 0,
433:       cooldown: 0,
434:       target: 'ally',
435:       kind: 'ether',
436:       desc: `아군 하나의 에테르를 30 회복합니다. 남은 수: ${this.items.ethers}`,
437:       disabled: this.items.ethers <= 0,
438:       reason: this.items.ethers <= 0 ? '에테르약 없음' : '',
439:       key: '6',
440:       item: true
441:     });
442:     return actions;
