450:   beginAction(actionId) {
451:     if (this.phase !== 'select') return false;
452:     const unit = this.getActive();
453:     if (!unit || unit.side !== 'ally') return false;
454:     if (actionId === 'cancel') {
455:       this.pendingAction = null;
456:       this.phase = 'select';
457:       this.cb.onUpdate?.();
458:       return true;
459:     }
460:     const action = this.getPlayerActions().find((a) => a.id === actionId);
461:     if (!action || action.disabled) return false;
462:     if (actionId === 'defend') {
463:       this.executeDefend(unit);
464:       return true;
465:     }
466:     if (action.target === 'self' || action.target === 'allEnemies' || action.target === 'allAllies' || action.target === 'randomEnemies' || action.target === 'randomAllies') {
467:       this.executeAction(unit, action, null);
468:       return true;
469:     }
470:     const targets = this.getValidTargets(unit, action);
471:     if (!targets.length) {
472:       this.setMessage('유효한 대상이 없습니다.');
473:       return false;
474:     }
475:     if (targets.length === 1) {
476:       this.executeAction(unit, action, targets[0].uid);
477:       return true;
478:     }
479:     this.pendingAction = action;
480:     this.phase = 'target';
481:     this.setMessage('대상을 선택하세요.');
482:     this.cb.onUpdate?.();
483:     return true;
484:   }
485: 
486:   selectTarget(uid) {
487:     if (this.phase !== 'target' || !this.pendingAction) return false;
488:     const unit = this.getActive();
489:     if (!unit) return false;
490:     const targets = this.getValidTargets(unit, this.pendingAction);
491:     if (!targets.some((t) => t.uid === uid)) return false;
492:     const action = this.pendingAction;
493:     this.pendingAction = null;
494:     this.executeAction(unit, action, uid);
495:     return true;
496:   }
497: 
498:   cancelTarget() {
499:     if (this.phase !== 'target') return false;
500:     this.pendingAction = null;
501:     this.phase = 'select';
502:     this.setMessage(`${this.getActive()?.name || ''}의 턴입니다.`);
503:     this.cb.onUpdate?.();
504:     return true;
505:   }
506: 
507:   toggleAuto() {
508:     this.auto = !this.auto;
509:     this.cb.onUpdate?.();
510:     if (this.auto && this.phase === 'select') setTimeout(() => this.autoAlly(this.getActive()), 200);
511:   }
512: 
513:   getValidTargets(unit, action) {
514:     const opposing = unit.side === 'ally' ? 'enemy' : 'ally';
515:     const same = unit.side;
516:     const targetType = action.target || (action.kind === 'heal' || action.kind === 'buff' ? 'ally' : 'enemy');
517:     let pool = [];
518:     if (targetType === 'enemy' || targetType === 'allEnemies' || targetType === 'randomEnemies') pool = this.getAlive(opposing);
519:     else if (targetType === 'ally' || targetType === 'allAllies' || targetType === 'randomAllies') pool = this.getAlive(same);
520:     else if (targetType === 'self') pool = [unit];
521:     else pool = this.getAlive(opposing);
522:     if (targetType === 'enemy' && (action.reach === 'front' || (!action.reach && action.kind === 'physical'))) {
523:       const front = pool.filter((u) => u.row === 'front');
524:       if (front.length) pool = front;
525:     }
526:     return pool;
527:   }
528: 
529:   resolveTargets(unit, action, targetUid, hitIndex = 0) {
530:     const targetType = action.target || 'enemy';
531:     if (targetUid) {
532:       const target = this.getUnit(targetUid);
533:       return target?.alive ? [target] : [];
534:     }
535:     if (targetType === 'self') return [unit];
536:     if (targetType === 'allEnemies' || targetType === 'allAllies') {
537:       return this.getValidTargets(unit, action);
538:     }
539:     if (targetType === 'randomEnemies' || targetType === 'randomAllies') {
540:       const pool = this.getValidTargets(unit, action);
541:       return pool.length ? [pick(pool)] : [];
542:     }
543:     const pool = this.getValidTargets(unit, action);
544:     return pool.length ? [pool[0]] : [];
545:   }
