547:   // -------------------------------------------------------------------------
548:   // Execution
549:   // -------------------------------------------------------------------------
550: 
551:   executeDefend(unit) {
552:     this.phase = 'resolving';
553:     this.setMessage(`${unit.name}이(가) 방어 태세를 취합니다.`);
554:     this.addLog(`<span class="ally">${unit.name}</span> 방어`, 'system');
555:     this.applyStatus(unit, { id: 'guard', turns: 2, value: 0.4 }, unit);
556:     unit.aether = Math.min(unit.maxAether, unit.aether + Math.round(unit.maxAether * 0.1));
557:     this.cb.onFx?.({ type: 'status', uid: unit.uid, text: '방어' });
558:     this.cb.onUpdate?.();
559:     setTimeout(() => this.finishTurn(unit), 500);
560:   }
561: 
562:   executeAction(unit, action, targetUid) {
563:     if (this.finished) return;
564:     this.phase = 'resolving';
565:     this.pendingAction = null;
566:     const cost = action.item ? 0 : this.costFor(unit, action);
567:     if (unit.aether < cost) {
568:       this.setMessage('에테르가 부족합니다.');
569:       this.phase = 'select';
570:       this.cb.onUpdate?.();
571:       return;
572:     }
573:     unit.aether -= cost;
574:     if (!action.item) unit.cooldowns[action.id] = action.cooldown || 0;
575: 
576:     const targetName = targetUid ? this.getUnit(targetUid)?.name : null;
577:     const targetText = targetName ? ` → ${targetName}` : '';
578:     this.addLog(`<span class="${unit.side}">${unit.name}</span> · <b>${action.name}</b>${targetText}`, 'action');
579:     this.setMessage(`${unit.name} · ${action.name}`);
580:     this.cb.onFx?.({ type: 'cast', uid: unit.uid, action });
581:     this.cb.onUpdate?.();
582: 
583:     let extraTurn = false;
584:     const targets = this.resolveTargets(unit, action, targetUid);
585:     const hits = action.hits || 1;
586:     const isRandom = action.target === 'randomEnemies' || action.target === 'randomAllies';
587: 
588:     if (action.item) {
589:       if (action.id === 'potion') {
590:         this.items.potions = Math.max(0, this.items.potions - 1);
591:         const target = targets[0] || unit;
592:         const amount = Math.round(target.maxHp * action.power);
593:         this.healUnit(target, amount, unit, '회복약');
594:         this.cb.onItemsChange?.({ ...this.items });
595:       } else if (action.id === 'ether') {
596:         this.items.ethers = Math.max(0, this.items.ethers - 1);
597:         const target = targets[0] || unit;
598:         target.aether = Math.min(target.maxAether, target.aether + 30);
599:         this.cb.onFx?.({ type: 'aether', uid: target.uid, amount: 30 });
600:         this.cb.onItemsChange?.({ ...this.items });
601:       }
602:       this.cb.onUpdate?.();
603:       setTimeout(() => this.finishTurn(unit), 520);
604:       return;
605:     }
606: 
607:     if (action.kind === 'heal') {
608:       const healTargets = action.target === 'allAllies' || action.target === 'allEnemies'
609:         ? this.getValidTargets(unit, action)
610:         : targets;
611:       for (const target of healTargets) {
612:         const amount = Math.round(this.spellPower(unit) * (action.power || 1) + target.maxHp * (action.heal || 0));
613:         this.healUnit(target, amount, unit, action.name);
614:         if (action.statuses?.length) {
615:           for (const s of action.statuses) this.applyStatus(target, s, unit);
616:         } else if (action.status) {
617:           this.applyStatus(target, action.status, unit);
618:         }
619:         if (action.cleanse) this.cleanse(target, action.cleanse);
620:       }
621:       if (action.special === 'undead_bane') {
622:         for (const enemy of this.getAlive(unit.side === 'ally' ? 'enemy' : 'ally')) {
623:           if (enemy.undead) {
624:             const dmg = Math.round(this.spellPower(unit) * 0.55);
625:             this.dealDamage(unit, enemy, { ...action, kind: 'magic', power: 0.55, status: null, statuses: null }, { bonus: 1.25 });
626:           }
627:         }
628:       }
629:     } else if (action.kind === 'buff' || action.kind === 'debuff') {
630:       const effectTargets = action.target === 'allEnemies' || action.target === 'allAllies'
631:         ? this.getValidTargets(unit, action)
632:         : targets;
633:       for (const target of effectTargets) {
634:         if (action.statuses?.length) {
635:           for (const s of action.statuses) this.applyStatus(target, s, unit);
636:         } else if (action.status) {
637:           this.applyStatus(target, action.status, unit);
638:         }
639:         if (action.heal) {
640:           const amount = Math.round(target.maxHp * action.heal);
641:           this.healUnit(target, amount, unit, action.name);
642:         }
643:         if (action.cleanse) this.cleanse(target, action.cleanse);
644:       }
645:       if (action.special === 'ashen_aegis') {
646:         for (const enemy of this.getAlive(unit.side === 'ally' ? 'enemy' : 'ally')) {
647:           this.applyStatus(enemy, { id: 'taunt', turns: 2, value: 1, source: unit.uid }, unit);
648:         }
649:       }
650:     } else {
651:       const hitTargets = isRandom ? [] : targets;
652:       for (let hit = 0; hit < hits; hit += 1) {
653:         const hitTarget = isRandom ? this.resolveTargets(unit, action, null, hit)[0] : hitTargets[hit % Math.max(1, hitTargets.length)];
654:         if (!hitTarget) continue;
655:         const beforeHp = hitTarget.hp;
656:         let bonus = 1;
657:         if (action.special === 'marked_bonus' && this.hasStatus(hitTarget, 'mark')) bonus *= 1.2;
658:         if (action.special === 'shadow_strike' && hitTarget.hp <= hitTarget.maxHp * 0.5) bonus *= 1.5;
659:         if (action.special === 'undead_bane' && hitTarget.undead) bonus *= 1.25;
660:         if (unit.trait === 'cinder_blood' && unit.hp <= unit.maxHp * 0.5) bonus *= 1.15;
661:         if (unit.kitId === 'nightglass_cutpurse') bonus *= 1.0;
662:         const critBonus = action.special === 'shadow_strike' ? 30 : 0;
663:         const dealt = this.dealDamage(unit, hitTarget, action, {
664:           bonus,
665:           pierce: action.pierce || 0,
666:           critBonus,
667:           sourceName: action.name
668:         });
669:         if (action.special === 'execute_chain' && !hitTarget.alive) extraTurn = true;
670:         if (action.special === 'steal' && dealt > 0) {
671:           const stolen = 8 + this.floor * 2;
672:           this.stolenGold += stolen;
673:           this.cb.onFx?.({ type: 'gold', amount: stolen });
674:         }
675:         if (action.special === 'ember_cascade' && dealt > 0 && this.lastDamageCrit) {
676:           unit.aether = Math.min(unit.maxAether, unit.aether + 3);
677:         }
678:         if (action.statuses?.length) {
679:           for (const s of action.statuses) if (hitTarget.alive) this.applyStatus(hitTarget, s, unit);
680:         } else if (action.status && hitTarget.alive) {
681:           this.applyStatus(hitTarget, action.status, unit);
682:         }
683:         if (action.special === 'dispel' && hitTarget.alive) this.dispel(hitTarget);
684:         if (action.special === 'steal' && dealt > 0 && beforeHp > 0) {
685:           // Stealing is intentionally small and shown in the result screen.
686:         }
687:       }
688:     }
689: 
690:     if (action.selfStatus) this.applyStatus(unit, action.selfStatus, unit);
691:     if (action.cleanse) this.cleanse(unit, action.cleanse);
692:     if (action.special === 'momentum') this.applyStatus(unit, { id: 'powerUp', turns: 1, value: 0.2 }, unit);
693:     if (action.special === 'wild_echo' && Math.random() < 0.2) {
694:       this.addLog('주문이 메아리칩니다!', 'system');
695:       setTimeout(() => {
696:         if (this.finished) return;
697:         const echoTarget = this.getAlive(unit.side === 'ally' ? 'enemy' : 'ally');
698:         if (echoTarget.length) {
699:           const target = pick(echoTarget);
700:           this.dealDamage(unit, target, { ...action, power: (action.power || 1) * 0.5, status: null, statuses: null }, { bonus: 1 });
701:           this.cb.onUpdate?.();
702:         }
703:       }, 260);
704:     }
705: 
706:     this.cb.onUpdate?.();
