// Data + engine integrity checks for Aetherborne: Warband (warband/* modules).
import { RACES, CLASSES, STATUSES, ENEMIES, ENCOUNTER_POOLS, FLOORS, STAT_KEYS, representativeKit, classById } from '/home/runner/work/PlayGround/PlayGround/js/warband/data.js';
import { computeCharacter, createCharacter, grantXp, xpNeeded, randomCharacter } from '/home/runner/work/PlayGround/PlayGround/js/warband/character.js';
import { generateDungeon, isWalkable, tileAt } from '/home/runner/work/PlayGround/PlayGround/js/warband/dungeon.js';
import { Battle } from '/home/runner/work/PlayGround/PlayGround/js/warband/battle.js';

const issues = [];
const ok = (cond, msg) => { if (!cond) issues.push(msg); };

// ---------------------------------------------------------------- data.js
ok(RACES.length === 12, `RACES length ${RACES.length}`);
ok(CLASSES.length === 12, `CLASSES length ${CLASSES.length}`);
const raceIds = new Set(RACES.map(r => r.id));
ok(raceIds.size === 12, 'duplicate race ids');
const validTargets = new Set(['enemy', 'ally', 'self', 'allEnemies', 'allAllies', 'randomEnemies', 'randomAllies']);
const validKinds = new Set(['physical', 'magic', 'mixed', 'heal', 'buff', 'debuff']);
for (const cls of CLASSES) {
  ok(cls.kits.length === 3, `${cls.id}: ${cls.kits.length} kits`);
  ok(cls.kits.filter(k => k.representative).length === 1, `${cls.id}: representative kit count`);
  ok(cls.ability && cls.ability.id && validTargets.has(cls.ability.target) && validKinds.has(cls.ability.kind), `${cls.id}: class ability shape`);
  ok(Array.isArray(cls.keyStats) && cls.keyStats.every(k => STAT_KEYS.includes(k)), `${cls.id}: keyStats`);
  for (const kit of cls.kits) {
    if (kit.representative) {
      const a = kit.ability;
      ok(a && a.id && validTargets.has(a.target) && validKinds.has(a.kind) && Number.isFinite(a.cost) && Number.isFinite(a.cooldown),
        `${cls.id}/${kit.id}: representative kit ability shape`);
    }
  }
}
for (const [id, s] of Object.entries(STATUSES)) ok(s.name && s.glyph && s.type, `STATUSES ${id}`);
for (const [id, e] of Object.entries(ENEMIES)) {
  ok(['hp', 'power', 'spell', 'defense', 'resolve', 'speed'].every(k => typeof e[k] === 'number' && e[k] > 0), `ENEMIES ${id} numeric fields`);
  const abilities = e.abilities || (e.ability ? [e.ability] : []);
  for (const a of abilities) {
    ok(validKinds.has(a.kind || 'physical'), `ENEMIES ${id} ability kind`);
    ok(!a.target || validTargets.has(a.target), `ENEMIES ${id} ability target ${a.target}`);
    ok(a.power == null || a.power > 0, `ENEMIES ${id} ability power`);
  }
}
for (const [floor, pool] of Object.entries(ENCOUNTER_POOLS)) {
  ok(pool.length >= 6, `pool ${floor} length ${pool.length}`);
  ok(pool.every(id => ENEMIES[id]), `pool ${floor} unknown enemy`);
}
ok(FLOORS.length === 5, 'FLOORS length');
for (const f of FLOORS) ok(f.accent && f.floor && f.wall && f.wallTop && f.fog, `FLOORS ${f.id} theme`);

// ---------------------------------------------------------- character.js
for (const race of RACES) {
  for (const cls of CLASSES) {
    const c = computeCharacter({ raceId: race.id, classId: cls.id, kitId: representativeKit(cls.id).id, level: 1, growth: {} });
    const d = c.derived;
    for (const [k, v] of Object.entries(d)) ok(Number.isFinite(v) && v >= 0, `derived ${k} not finite for ${race.id}/${cls.id}: ${v}`);
    ok(d.maxHp >= 60 && d.maxHp <= 220, `maxHp out of band for ${race.id}/${cls.id}: ${d.maxHp}`);
    ok(d.speed >= 8 && d.speed <= 60, `speed out of band for ${race.id}/${cls.id}: ${d.speed}`);
    ok(d.crit >= 0 && d.crit <= 60 && d.evade >= 0 && d.evade <= 40, `crit/evade out of band ${race.id}/${cls.id}`);
  }
}
// trait effect spot-checks
const sylvan = computeCharacter({ raceId: 'sylvan', classId: 'ranger', kitId: 'tidewatch_tracker', level: 1, growth: {} });
const emberkin = computeCharacter({ raceId: 'emberkin', classId: 'ranger', kitId: 'tidewatch_tracker', level: 1, growth: {} });
ok(sylvan.derived.evade > emberkin.derived.evade, `sylvan verdant_step gives no evade bonus (${sylvan.derived.evade} vs ${emberkin.derived.evade})`);
const ironhide = computeCharacter({ raceId: 'ironhide', classId: 'fighter', kitId: 'vanguard_blade', level: 1, growth: {} });
const emberFighter = computeCharacter({ raceId: 'emberkin', classId: 'fighter', kitId: 'vanguard_blade', level: 1, growth: {} });
ok(ironhide.derived.maxHp > emberFighter.derived.maxHp * 1.05, `thick_hide hp mult missing`);
const ash = computeCharacter({ raceId: 'ashwing', classId: 'fighter', kitId: 'vanguard_blade', level: 1, growth: {} });
ok(ash.derived.crit > emberFighter.derived.crit, 'glide crit bonus missing');
const grave = computeCharacter({ raceId: 'graveborn', classId: 'guardian', kitId: 'bulwark_ash', level: 1, growth: {} });
const emberGuardian = computeCharacter({ raceId: 'emberkin', classId: 'guardian', kitId: 'bulwark_ash', level: 1, growth: {} });
ok(grave.derived.maxHp > emberGuardian.derived.maxHp, 'graveborn vitality mods');
// xp curve
const ch = createCharacter({ name: 'T', raceId: 'emberkin', classId: 'fighter', kitId: 'vanguard_blade', level: 1 });
const lv0 = ch.level;
grantXp(ch, xpNeeded(1));
ok(ch.level === lv0 + 1, `grantXp level up failed (${lv0} -> ${ch.level})`);
ok(ch.hp > 0 && ch.hp <= computeCharacter(ch).derived.maxHp, 'level up hp clamp');

// ----------------------------------------------------------- dungeon.js
function bfsReachable(d, from) {
  const seen = new Set([`${from.x},${from.y}`]);
  const q = [from];
  while (q.length) {
    const cur = q.shift();
    for (const [dx, dy] of [[1,0],[-1,0],[0,1],[0,-1]]) {
      const nx = cur.x + dx, ny = cur.y + dy;
      const k = `${nx},${ny}`;
      if (seen.has(k) || !isWalkable(d, nx, ny)) continue;
      seen.add(k);
      q.push({ x: nx, y: ny });
    }
  }
  return seen;
}
let dungeonChecks = 0;
for (let i = 0; i < 240; i += 1) {
  const seed = 1000 + i * 7919;
  const floor = (i % 6) + 1;
  const d = generateDungeon(floor, seed);
  dungeonChecks += 1;
  ok(d.encounters.length >= 3 && d.encounters.length <= 4, `seed ${seed} floor ${floor}: encounters ${d.encounters.length}`);
  ok(d.chests.length >= 1 && d.chests.length <= 2, `seed ${seed}: chests ${d.chests.length}`);
  ok(d.shrines.length <= 1, `seed ${seed}: shrines ${d.shrines.length}`);
  const reach = bfsReachable(d, d.start);
  ok(reach.has(`${d.stairs.x},${d.stairs.y}`), `seed ${seed}: stairs unreachable`);
  const all = [...d.encounters, ...d.chests, ...d.shrines];
  for (const e of all) {
    ok(tileAt(d, e.x, e.y) === 1, `seed ${seed}: entity on wall ${e.type}@${e.x},${e.y}`);
    ok(reach.has(`${e.x},${e.y}`), `seed ${seed}: ${e.type} unreachable`);
    ok(!(e.x === d.start.x && e.y === d.start.y), `seed ${seed}: entity on start`);
    ok(!(e.x === d.stairs.x && e.y === d.stairs.y), `seed ${seed}: entity on stairs`);
  }
  const boss = d.encounters.find(e => e.encounterType === 'boss');
  if (floor === 3 || floor === 5) ok(boss, `seed ${seed} floor ${floor}: boss floor missing boss`);
  else ok(!boss, `seed ${seed} floor ${floor}: unexpected boss`);
  // unique entity positions
  const keys = new Set(all.map(e => `${e.x},${e.y}`));
  ok(keys.size === all.length, `seed ${seed}: overlapping entities`);
}
console.log(`dungeon generation checked: ${dungeonChecks} layouts`);

// ------------------------------------------------------------ battle.js
// Deterministic-ish fast scheduler: replaces setTimeout inside Battle sims.
function makeScheduler() {
  let time = 0;
  let running = false;
  const q = [];
  let counter = 0;
  const realSetTimeout = globalThis.setTimeout;
  return {
    install() {
      globalThis.setTimeout = (fn, delay = 0) => { q.push({ t: time + (delay || 0), fn, i: counter++ }); q.sort((a, b) => a.t - b.t || a.i - b.i); return counter; };
      globalThis.clearTimeout = () => {};
    },
    uninstall() { globalThis.setTimeout = realSetTimeout; },
    async run_until(done, maxSteps = 200000) {
      running = true;
      let steps = 0;
      while (running && q.length && steps < maxSteps) {
        const item = q.shift();
        time = Math.max(time, item.t);
        steps += 1;
        item.fn();
        if (done()) running = false;
        if (steps % 400 === 0) await new Promise(r => setImmediate(r));
      }
      globalThis.setTimeout = realSetTimeout;
      return { steps, exhausted: steps >= maxSteps };
    },
  };
}

function buildParty(specs, level) {
  return specs.map(({ raceId, classId, kitId, name }) => {
    const c = createCharacter({ name: name || classId, raceId, classId, kitId: kitId || representativeKit(classId).id, level });
    return c;
  });
}

async function simBattle({ floor, encounterType, partyLevel, partySpec, bossId, seed }) {
  const sched = makeScheduler();
  sched.install();
  const party = buildParty(partySpec, partyLevel);
  const battle = new Battle({
    party,
    floor,
    encounter: { encounterType, bossId, floor },
    items: { potions: 2, ethers: 1 },
    callbacks: { onUpdate() {}, onLog() {}, onFx() {}, onItemsChange() {} },
  });
  battle.auto = true;
  let result = null;
  battle.cb.onEnd = (r) => { result = r; };
  // start() uses setTimeout -> goes through scheduler
  battle.start();
  const info = await sched.run_until(() => result != null || battle.finished);
  const errors = [];
  if (!result) errors.push('battle never finished');
  if (info.exhausted) errors.push('scheduler exhausted');
  // sanity: all ally hp within bounds, result shape
  if (result) {
    ok(['victory', 'defeat'].includes(result.result), `bad result ${result.result}`);
    ok(Number.isFinite(result.xp) && result.xp >= 0, 'xp');
    ok(Number.isFinite(result.gold) && result.gold >= 0, 'gold');
    for (const u of result.units) ok(u.hp >= 0 && u.hp <= u.maxHp, 'unit hp bounds');
  }
  return { result, rounds: battle.round, errors };
}

const ALL12 = CLASSES.map(c => ({ classId: c.id }));
const campaign = [
  { floor: 1, partyLevel: 1 },
  { floor: 2, partyLevel: 3 },
  { floor: 3, partyLevel: 5, bossId: 'warden' },
  { floor: 4, partyLevel: 7 },
  { floor: 5, partyLevel: 9, bossId: 'crown' },
];

console.log('--- battle sims: all-12-class party, expected progression levels');
for (const step of campaign) {
  const N = 12;
  let wins = 0;
  let roundSum = 0;
  const errs = [];
  for (let i = 0; i < N; i += 1) {
    const { result, rounds, errors } = await simBattle({ floor: step.floor, encounterType: step.bossId ? 'boss' : 'normal', partyLevel: step.partyLevel, partySpec: ALL12, bossId: step.bossId, seed: i });
    if (result?.result === 'victory') wins += 1;
    roundSum += rounds;
    errs.push(...errors);
  }
  console.log(`floor ${step.floor} (Lv${step.partyLevel}${step.bossId ? ' boss' : ''}): win ${wins}/${N}, avg rounds ${(roundSum / N).toFixed(1)}${errs.length ? ' ERRORS: ' + errs.join(';') : ''}`);
  ok(errs.length === 0, `floor ${step.floor} sim errors`);
}

console.log('--- battle sims: single-class parties (exercises every kit ability)');
for (const cls of CLASSES) {
  const spec = [0,1,2,3,4,5].map(i => ({ classId: cls.id }));
  const { result, errors } = await simBattle({ floor: 2, encounterType: 'normal', partyLevel: 3, partySpec: spec, seed: 3 });
  ok(errors.length === 0, `${cls.id} sim errors: ${errors.join(';')}`);
  console.log(`${cls.id.padEnd(11)} ${result ? result.result : 'NO RESULT'} (rounds ok)`);
}

console.log('--- battle sims: level-1 party vs floor 1 (fresh-save difficulty)');
{
  let wins = 0; const N = 20;
  for (let i = 0; i < N; i += 1) {
    const { result } = await simBattle({ floor: 1, encounterType: 'normal', partyLevel: 1, partySpec: ALL12, seed: i });
    if (result?.result === 'victory') wins += 1;
  }
  console.log(`fresh party win rate floor 1: ${wins}/${N}`);
  ok(wins >= N * 0.5, `floor-1 win rate too low: ${wins}/${N}`);
}

// ---------------------------------------------------------------- report
console.log('\n==============================');
if (issues.length) {
  console.log(`ISSUES (${issues.length}):`);
  for (const i of issues) console.log(' - ' + i);
  process.exitCode = 1;
} else {
  console.log('ALL INTEGRITY CHECKS PASSED');
}

