        time = Math.max(time, item.t);
        steps += 1;
        item.fn();
        if (done()) running = false;
        if (steps % 400 === 0) await new Promise(r => setImmediate(r));
      }
      globalThis.setTimeout = realSetTimeout;
      return { steps, exhausted: steps >= maxSteps };
    },
    get pending() { return q.length; },
  };
}

const ALL12 = CLASSES.map(c => ({ classId: c.id }));
async function simBattle({ floor, encounterType, partyLevel, bossId }) {
  const sched = makeScheduler();
  sched.install();
  const party = ALL12.map(({ classId }) => createCharacter({ name: classId, raceId: 'emberkin', classId, kitId: representativeKit(classId).id, level: partyLevel }));
  const battle = new Battle({
    party, floor, encounter: { encounterType, bossId, floor }, items: { potions: 2, ethers: 1 },
    callbacks: { onUpdate() {}, onLog() {}, onFx() {}, onItemsChange() {} },
  });
  battle.auto = true;
  let result = null;
  battle.cb.onEnd = (r) => { result = r; };
  battle.start();
  const info = await sched.run_until(() => result != null || battle.finished);
  console.log(`floor=${floor} lv=${partyLevel} steps=${info.steps} pendingAfter=${sched.pending} phase=${battle.phase} finished=${battle.finished} result=${result?.result} round=${battle.round}`);
}
await simBattle({ floor: 1, encounterType: 'normal', partyLevel: 1 });
