// Full E2E playthrough of Aetherborne: Warband in headless Chromium.
import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';

const BASE = 'http://localhost:8901/index.html';
const errors = [];
const steps = [];
const step = (name, detail = '') => { steps.push(name + (detail ? ` — ${detail}` : '')); console.log(`✔ ${name}${detail ? ' — ' + detail : ''}`); };

const browser = await chromium.launch();
const context = await browser.newContext({ viewport: { width: 1280, height: 800 } });
await context.addInitScript(() => { try { localStorage.clear(); } catch {} });
const page = await context.newPage();
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
page.on('requestfailed', (r) => errors.push('REQFAIL: ' + r.url()));

const shot = (name) => page.screenshot({ path: `/tmp/opencode/e2e-${name}.jpg`, quality: 70, type: 'jpeg' });
const active = () => page.evaluate(() => document.querySelector('.screen.is-active')?.id || null);
const app = () => page.evaluate(() => {
  const a = window.__warband;
  return {
    mode: a.mode,
    pos: a.run?.pos ? { ...a.run.pos } : null,
    floor: a.run?.floor ?? null,
    gold: a.run?.gold ?? null,
    potions: a.run?.potions ?? null,
    encounters: a.dungeon ? a.dungeon.encounters.map(e => ({ id: e.id, x: e.x, y: e.y, cleared: !!e.cleared, type: e.encounterType })) : [],
    chests: a.dungeon ? a.dungeon.chests.map(c => ({ x: c.x, y: c.y, opened: !!c.opened })) : [],
    shrines: a.dungeon ? a.dungeon.shrines.map(s => ({ x: s.x, y: s.y, used: !!s.used })) : [],
    stairs: a.dungeon ? { ...a.dungeon.stairs } : null,
    w: a.dungeon?.width, h: a.dungeon?.height,
    party: a.party.filter(Boolean).map(m => ({ name: m.name, level: m.level, hp: m.hp })),
  };
});
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

// BFS path over walkable tiles; returns array of 'w'|'a'|'s'|'d' moves.
function pathKeys(from, to, dungeon) {
  const key = (x, y) => y * dungeon.w + x;
  const walk = (x, y) => x >= 0 && y >= 0 && x < dungeon.w && y < dungeon.h && dungeonTiles[key(x, y)] === 1;
  const dungeonTiles = dungeon.tiles;
  if (!walk(to.x, to.y)) return null;
  const prev = new Map();
  const q = [from];
  prev.set(`${from.x},${from.y}`, null);
  while (q.length) {
    const cur = q.shift();
    if (cur.x === to.x && cur.y === to.y) break;
    for (const [dx, dy, k] of [[1, 0, 'd'], [-1, 0, 'a'], [0, 1, 's'], [0, -1, 'w']]) {
      const nx = cur.x + dx, ny = cur.y + dy;
      const id = `${nx},${ny}`;
      if (prev.has(id) || !walk(nx, ny)) continue;
      prev.set(id, { from: `${cur.x},${cur.y}`, key: k });
      q.push({ x: nx, y: ny });
    }
  }
  const path = [];
  let cur = `${to.x},${to.y}`;
  while (cur && cur !== `${from.x},${from.y}`) {
    const p = prev.get(cur);
    if (!p) return null;
    path.unshift(p.key);
    cur = p.from;
  }
  return path;
}

async function walkTo(target) {
  for (let guard = 0; guard < 400; guard += 1) {
    const a = await app();
    if (a.pos.x === target.x && a.pos.y === target.y) return true;
    // stop early if we stepped onto an entity or a battle started
    const keys = pathKeys(a.pos, target, a);
    if (!keys || !keys.length) return a.pos.x === target.x && a.pos.y === target.y;
    const nextKey = keys[0];
    await page.keyboard.press(nextKey);
    await sleep(150);
    const mode = await active();
    if (mode !== 'screen-dungeon') return false; // battle or overlay started
  }
  return false;
}

async function waitBattleEnd(timeoutMs = 150000) {
  const t0 = Date.now();
  while (Date.now() - t0 < timeoutMs) {
    const overlayVisible = await page.evaluate(() => !document.getElementById('overlay')?.classList.contains('hidden'));
    if (overlayVisible) {
      const hasVictory = await page.evaluate(() => !!document.getElementById('btn-victory-continue'));
      const hasDefeat = await page.evaluate(() => !!document.getElementById('btn-defeat-retry'));
      if (hasVictory) return 'victory';
      if (hasDefeat) return 'defeat';
    }
    await sleep(500);
  }
  return 'timeout';
}

// ------------------------------------------------------------------ title
await page.goto(BASE, { waitUntil: 'networkidle' });
await sleep(1200);
if (await active() !== 'screen-title') throw new Error('title screen not active');
step('title screen loads');

await page.click('#btn-manual');
await sleep(400);
for (const tab of ['races', 'classes', 'kits', 'combat', 'overview']) {
  await page.click(`[data-manual-tab="${tab}"]`);
  await sleep(120);
}
await shot('manual');
await page.click('#btn-manual-close-2');
await sleep(200);
step('field manual opens, all 5 tabs render');
if (await active() !== 'screen-title') throw new Error('manual close failed');

// ------------------------------------------------------------------ creation
await page.click('#btn-new');
await sleep(400);
if (await active() !== 'screen-create') throw new Error('creation screen not active');
await page.click('[data-race="emberkin"]');
await sleep(250);
await shot('create-race');
await page.click('#btn-create-next');
await sleep(250);
await page.click('[data-class="fighter"]');
await sleep(250);
await shot('create-class');
await page.click('#btn-create-next');
await sleep(250);
const kitButtons = await page.$$('.option-card[data-kit]');
if (kitButtons.length !== 3) throw new Error(`expected 3 kit cards, got ${kitButtons.length}`);
await page.click('.option-card[data-kit]:not(.is-locked)');
await sleep(250);
await page.click('#btn-create-next');
await sleep(250);
await shot('create-stats');
await page.click('#btn-create-next');
await sleep(300);
await page.fill('#char-name', '테리아');
await page.click('#btn-create-next');
await sleep(500);
if (await active() !== 'screen-party') throw new Error('party screen not reached after finalize');
step('creation wizard: emberkin fighter · vanguard blade · named 테리아');

// formation swap: click slot 0 then slot 1 (both filled after autofill)
await page.click('#btn-autofill');
await sleep(500);
const count = await page.textContent('#party-count');
if (count.trim() !== '6 / 6') throw new Error(`autofill failed: ${count}`);
step('autofill muster fills 6/6');
await page.click('[data-slot="0"]');
await sleep(200);
await page.click('[data-slot="1"]');
await sleep(300);
const rosterNames = await page.$$eval('#party-roster .roster-card', els => els.map(e => e.querySelector('h4').textContent));
if (rosterNames.length !== 6) throw new Error('roster should list 6 members');
await shot('party');
step('formation swap works, roster lists 6');

// ------------------------------------------------------------------ dungeon
await page.click('#btn-begin');
await sleep(800);
if (await active() !== 'screen-dungeon') throw new Error('dungeon screen not active');
const hud = await page.evaluate(() => ({
  floorName: document.getElementById('dungeon-floor-name')?.textContent,
  objective: document.getElementById('dungeon-objective')?.textContent,
  chips: document.querySelectorAll('#party-bar .party-chip').length,
}));
if (!hud.floorName || hud.chips !== 6) throw new Error('dungeon HUD incomplete: ' + JSON.stringify(hud));
step('dungeon entered: ' + hud.floorName + ' · objective ' + hud.objective + ' · 6 party chips');
await sleep(700);
await shot('dungeon');

// abandon overlay cancel
await page.keyboard.press('Escape');
await sleep(400);
if (!(await page.evaluate(() => !!document.getElementById('btn-abandon-cancel')))) throw new Error('abandon overlay missing');
await page.click('#btn-abandon-cancel');
await sleep(300);
step('abandon overlay opens and cancels');

// clear all encounters, opening chests/shrines en route
let clearedCount = 0;
const totalEncounters = (await app()).encounters.length;
while (clearedCount < totalEncounters) {
  const a = await app();
  const remaining = a.encounters.filter(e => !e.cleared);
  if (!remaining.length) break;
  // nearest unopened chest or unused shrine along the way? prioritize progress: nearest encounter
  const target = remaining.map(e => ({ e, d: Math.abs(e.x - a.pos.x) + Math.abs(e.y - a.pos.y) })).sort((x, y) => x.d - y.d)[0].e;
  const reached = await walkTo({ x: target.x, y: target.y });
  const mode = await active();
  if (mode === 'screen-battle') {
    await sleep(900);
    const unitCount = await page.$$eval('.unit', els => els.length);
    if (unitCount !== 12) throw new Error(`expected 12 units in battle, got ${unitCount}`);
    await page.keyboard.press('a'); // auto-battle on
    await sleep(400);
    await shot('battle-mid');
    const outcome = await waitBattleEnd();
    if (outcome === 'timeout') throw new Error('battle never ended');
    if (outcome === 'defeat') {
      step('battle DEFEAT (auto) → retrying');
      await page.click('#btn-defeat-retry');
      await sleep(900);
      await page.keyboard.press('a');
      const outcome2 = await waitBattleEnd();
      if (outcome2 !== 'victory') throw new Error('retry also failed: ' + outcome2);
    }
    await page.click('#btn-victory-continue');
    await sleep(700);
    if (await active() !== 'screen-dungeon') throw new Error('did not return to dungeon after victory');
    clearedCount += 1;
    const a2 = await app();
    step(`battle ${clearedCount}/${totalEncounters} won`, `gold=${a2.gold} potions=${a2.potions} party=${a2.party.map(p => 'Lv' + p.level).join(',')}`);
  } else if (mode === 'screen-dungeon') {
    if (!reached) throw new Error('could not reach encounter at ' + JSON.stringify(target));
    throw new Error('on encounter tile but no battle started');
  } else {
    throw new Error('unexpected screen: ' + mode);
  }
}
step(`all ${totalEncounters} floor-1 encounters cleared`);

// grab chest + shrine before descending
const a3 = await app();
for (const c of a3.chests.filter(c => !c.opened)) {
  await walkTo({ x: c.x, y: c.y });
  await sleep(300);
}
for (const s of a3.shrines.filter(s => !s.used)) {
  await walkTo({ x: s.x, y: s.y });
  await sleep(300);
}
const a4 = await app();
step(`treasure: gold=${a4.gold} potions=${a4.potions}, chests opened=${a4.chests.filter(c => c.opened).length}/${a4.chests.length}, shrine used=${a4.shrines.filter(s => s.used).length}/${a4.shrines.length}`);

// descend
await walkTo(a4.stairs);
await sleep(200);
await page.keyboard.press('e');
await sleep(500);
if (!(await page.evaluate(() => !!document.getElementById('btn-descend')))) throw new Error('descend overlay missing');
await shot('descend');
await page.click('#btn-descend');
await sleep(900);
const a5 = await app();
if (a5.floor !== 2) throw new Error('descend failed, floor=' + a5.floor);
step(`descended to floor ${a5.floor} (${(await page.textContent('#dungeon-floor-name')).trim()})`);

// ------------------------------------------------------------------ defeat → retry flow on floor 2
const target = (await app()).encounters.find(e => !e.cleared);
if (target) {
  const reached = await walkTo({ x: target.x, y: target.y });
  const mode = await active();
  if (mode !== 'screen-battle') throw new Error('floor-2 battle did not start');
  await sleep(900);
  // force near-defeat to exercise the defeat path quickly
  await page.evaluate(() => {
    const b = window.__warband.battle;
    for (const u of b.units) if (u.side === 'ally') { u.hp = 1; u.maxHp = 40; }
  });
  await page.keyboard.press('a');
  const outcome = await waitBattleEnd(180000);
  if (outcome !== 'defeat') throw new Error('expected defeat overlay, got ' + outcome);
  step('forced defeat → defeat overlay shown');
  await shot('defeat');
  await page.click('#btn-defeat-retry');
  await sleep(1000);
  if (await active() !== 'screen-battle') throw new Error('retry did not restart battle');
  await page.keyboard.press('a');
  const outcome2 = await waitBattleEnd(180000);
  if (outcome2 !== 'victory') throw new Error('retry battle result: ' + outcome2);
  await page.click('#btn-victory-continue');
  await sleep(700);
  step('defeat → 다시 싸우기 restores 60% HP and retry wins');
}

// ------------------------------------------------------------------ save / continue
await page.reload({ waitUntil: 'networkidle' });
await sleep(1000);
const contDisabled = await page.$eval('#btn-continue', el => el.disabled);
if (contDisabled) throw new Error('continue button disabled after reload despite active run');
await page.click('#btn-continue');
await sleep(900);
const a6 = await app();
if (a6.floor !== 2 || await active() !== 'screen-dungeon') throw new Error('resume failed: floor=' + a6.floor + ' screen=' + await active());
step('save/continue: run resumes on floor ' + a6.floor + ' at saved position');

// sound toggle
const before = await page.textContent('#btn-sound');
await page.click('#btn-sound');
await sleep(200);
const after = await page.textContent('#btn-sound');
if (before === after) throw new Error('sound toggle did not change button');
step('sound toggle works');

// ------------------------------------------------------------------ mobile layout spot-check
const mob = await context.newPage();
await mob.setViewportSize({ width: 390, height: 844 });
await mob.goto(BASE, { waitUntil: 'networkidle' });
await sleep(1000);
await mob.screenshot({ path: '/tmp/opencode/e2e-mobile-title.jpg', quality: 60, type: 'jpeg' });
const mobileOk = await mob.evaluate(() => {
  const el = document.elementFromPoint(200, 400);
  return !!el;
});
await mob.close();
step('mobile viewport renders (390px)', mobileOk ? 'ok' : '??');

// ------------------------------------------------------------------ report
console.log('\n==============================');
if (errors.length) {
  console.log(`CONSOLE/PAGE ERRORS (${errors.length}):`);
  for (const e of [...new Set(errors)].slice(0, 20)) console.log(' - ' + e);
} else {
  console.log('NO console/page errors during the whole playthrough');
}
await browser.close();
if (errors.length) process.exitCode = 1;

