// Finale test: seeded floor-5 run → clear encounters + crown boss → campaign victory → endless floor 6. Also dpad touch input.
import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';

const errors = [];
const browser = await chromium.launch();
const context = await browser.newContext({ viewport: { width: 1280, height: 800 } });
const page = await context.newPage();
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
const sleep = ms => new Promise(r => setTimeout(r, ms));

// Build a valid save on a blank page first
await page.goto('http://localhost:8901/index.html', { waitUntil: 'networkidle' });
await page.evaluate(() => {
  const classes = ['fighter', 'guardian', 'ranger', 'cleric', 'mage', 'thief'];
  const races = ['emberkin', 'stoneborn', 'sylvan', 'sunfolk', 'runeblood', 'duskling'];
  const party = classes.map((classId, i) => {
    const growth = { vitality: 8 };
    if (classId === 'fighter' || classId === 'guardian' || classId === 'thief') growth.might = 8;
    if (classId === 'ranger') growth.agility = 8;
    if (classId === 'cleric' || classId === 'mage') growth.intellect = 8;
    return {
      id: 'test_' + i, name: '영웅' + (i + 1), raceId: races[i], classId,
      kitId: classId === 'fighter' ? 'vanguard_blade' : classId === 'guardian' ? 'bulwark_ash' : classId === 'ranger' ? 'tidewatch_tracker' : classId === 'cleric' ? 'dawnkeeper' : classId === 'mage' ? 'prism_scholar' : 'nightglass_cutpurse',
      level: 9, xp: 0, growth, hp: 9999, aether: 999
    };
  });
  const run = { floor: 5, seed: 20261105, gold: 100, potions: 3, ethers: 3, pos: null, cleared: [], opened: [], used: [], startedAt: Date.now() };
  localStorage.setItem('aetherborne_warband_v1', JSON.stringify({ version: 1, party, run, settings: { sound: true, music: true } }));
});
await page.reload({ waitUntil: 'networkidle' });
await sleep(900);
const note = await page.textContent('#title-note');
if (!note.includes('왕관의 심장')) throw new Error('seeded run not recognized: ' + note);
console.log('✔ seeded floor-5 run loaded:', note.trim());

await page.click('#btn-continue');
await sleep(1000);
const floorName = (await page.textContent('#dungeon-floor-name')).trim();
if (floorName !== '왕관의 심장') throw new Error('expected crown floor, got ' + floorName);
console.log('✔ floor 5 entered:', floorName);

// dungeon helpers
const getApp = () => page.evaluate(() => {
  const a = window.__warband;
  return {
    pos: { ...a.run.pos }, encounters: a.dungeon.encounters.map(e => ({ x: e.x, y: e.y, cleared: !!e.cleared, type: e.encounterType })),
    chests: a.dungeon.chests.map(c => ({ x: c.x, y: c.y, opened: !!c.opened })),
    stairs: { ...a.dungeon.stairs }, w: a.dungeon.width, h: a.dungeon.height, tiles: Array.from(a.dungeon.tiles),
  };
});
function pathKeys(from, to, d) {
  const key = (x, y) => y * d.w + x;
  const walk = (x, y) => x >= 0 && y >= 0 && x < d.w && y < d.h && d.tiles[key(x, y)] === 1;
  const prev = new Map([[`${from.x},${from.y}`, null]]);
  const q = [from];
  while (q.length) {
    const cur = q.shift();
    if (cur.x === to.x && cur.y === to.y) break;
    for (const [dx, dy, k] of [[1, 0, 'd'], [-1, 0, 'a'], [0, 1, 's'], [0, -1, 'w']]) {
      const nx = cur.x + dx, ny = cur.y + dy, id = `${nx},${ny}`;
      if (prev.has(id) || !walk(nx, ny)) continue;
      prev.set(id, { from: `${cur.x},${cur.y}`, key: k });
      q.push({ x: nx, y: ny });
    }
  }
  const path = [];
  let cur = `${to.x},${to.y}`;
  while (cur && cur !== `${from.x},${from.y}`) {
    const p = prev.get(cur);
    if (!p) return null;
    path.unshift(p.key);
    cur = p.from;
  }
  return path;
}
async function walkTo(target) {
  for (let i = 0; i < 400; i += 1) {
    const a = await getApp();
    if (a.pos.x === target.x && a.pos.y === target.y) return true;
    const keys = pathKeys(a.pos, target, a);
    if (!keys?.length) return false;
    await page.keyboard.press(keys[0]);
    await sleep(150);
    if (await page.evaluate(() => document.querySelector('.screen.is-active')?.id) !== 'screen-dungeon') return false;
  }
  return false;
}
async function waitOverlayButton(id, timeout = 200000) {
  const t0 = Date.now();
  while (Date.now() - t0 < timeout) {
    if (await page.evaluate(id2 => !document.getElementById('overlay')?.classList.contains('hidden') && !!document.getElementById(id2), id)) return true;
    await sleep(500);
  }
  return false;
}

// dpad touch check before combat: hold right on the dpad, confirm position changes
const before = (await getApp()).pos;
await page.click('.dpad-btn.right');
await sleep(250);
await page.evaluate(() => document.querySelector('.dpad-btn.right')?.dispatchEvent(new PointerEvent('pointerup')));
const after = (await getApp()).pos;
if (before.x === after.x && before.y === after.y) throw new Error('dpad touch movement did not work');
console.log('✔ touch D-pad moves the party', before, '→', after);

// clear the 3 normal encounters, then the boss
const total = (await getApp()).encounters.length;
console.log('floor-5 encounters:', total);
let cleared = 0;
while (cleared < total) {
  const a = await getApp();
  const remaining = a.encounters.filter(e => !e.cleared);
  if (!remaining.length) break;
  const target = remaining.map(e => ({ e, d: Math.abs(e.x - a.pos.x) + Math.abs(e.y - a.pos.y) })).sort((x, y) => x.d - y.d)[0].e;
  const isBoss = target.type === 'boss';
  const reached = await walkTo({ x: target.x, y: target.y });
  if (await page.evaluate(() => document.querySelector('.screen.is-active')?.id) !== 'screen-battle') {
    throw new Error('battle did not start (boss=' + isBoss + ', reached=' + reached + ')');
  }
  await sleep(900);
  await page.keyboard.press('a');
  if (!await waitOverlayButton('btn-victory-continue')) throw new Error('floor-5 battle did not finish (boss=' + isBoss + ')');
  await page.screenshot({ path: `/tmp/opencode/e2e-finale-victory.jpg`, quality: 70, type: 'jpeg' });
  await page.click('#btn-victory-continue');
  await sleep(800);
  cleared += 1;
  console.log(`✔ ${isBoss ? 'CROWN BOSS' : 'encounter'} ${cleared}/${total} cleared`);
}

if (!await waitOverlayButton('btn-victory-continue', 15000)) throw new Error('final victory overlay missing');
// after the boss on floor 5 the button should read 왕관의 심장 보기
const label = (await page.textContent('#btn-victory-continue')).trim();
console.log('✔ final victory button:', label);
await page.click('#btn-victory-continue');
await sleep(900);
const campaignVisible = await page.evaluate(() => !!document.getElementById('btn-campaign-continue'));
if (!campaignVisible) throw new Error('campaign victory overlay missing');
await page.screenshot({ path: '/tmp/opencode/e2e-campaign-victory.jpg', quality: 70, type: 'jpeg' });
console.log('✔ campaign victory overlay shown (공허의 왕관 격파)');

await page.click('#btn-campaign-continue');
await sleep(1000);
const floor6 = await page.evaluate(() => ({ floor: window.__warband.run.floor, name: document.getElementById('dungeon-floor-name').textContent, encounters: window.__warband.dungeon.encounters.length }));
if (floor6.floor !== 6) throw new Error('endless descent failed: ' + JSON.stringify(floor6));
console.log('✔ endless mode: floor 6 loaded (' + floor6.name + '), encounters:', floor6.encounters);
await page.screenshot({ path: '/tmp/opencode/e2e-floor6.jpg', quality: 70, type: 'jpeg' });

// descend again on floor 6 to prove the loop continues
for (const s of [1, 2]) {
  const a = await getApp();
  const target = a.encounters.find(e => !e.cleared);
  if (target) {
    await walkTo({ x: target.x, y: target.y });
    if (await page.evaluate(() => document.querySelector('.screen.is-active')?.id) === 'screen-battle') {
      await sleep(900);
      await page.keyboard.press('a');
