// Corrected campaign simulation: 6-member parties, organic XP progression floor by floor.
import { CLASSES, representativeKit } from '/home/runner/work/PlayGround/PlayGround/js/warband/data.js';
import { createCharacter, grantXp } from '/home/runner/work/PlayGround/PlayGround/js/warband/character.js';
import { Battle } from '/home/runner/work/PlayGround/PlayGround/js/warband/battle.js';

function makeScheduler() {
  let time = 0;
  let running = false;
  const q = [];
  let counter = 0;
  const real = globalThis.setTimeout;
  return {
    install() { globalThis.setTimeout = (fn, delay = 0) => { q.push({ t: time + (delay || 0), fn, i: counter++ }); q.sort((a, b) => a.t - b.t || a.i - b.i); return counter; }; globalThis.clearTimeout = () => {}; },
    uninstall() { globalThis.setTimeout = real; },
    async run_until(done, maxSteps = 400000) {
      running = true;
      let steps = 0;
      while (running && q.length && steps < maxSteps) {
        const item = q.shift();
        time = Math.max(time, item.t);
        steps += 1;
        item.fn();
        if (done()) running = false;
        if (steps % 500 === 0) await new Promise(r => setImmediate(r));
      }
      globalThis.setTimeout = real;
      return steps;
    },
  };
}

// One auto-battle; returns {result, logs?}. Callbacks swallow everything.
async function simBattle(party, floor, encounterType, bossId) {
  const sched = makeScheduler();
  sched.install();
  const battle = new Battle({
    party, floor, encounter: { encounterType, bossId, floor }, items: { potions: 2, ethers: 1 },
    callbacks: { onUpdate() {}, onLog() {}, onFx() {}, onItemsChange() {}, onEnd() {} },
  });
  battle.auto = true;
  let result = null;
  battle.cb.onEnd = (r) => { result = r; };
  battle.start();
  const steps = await sched.run_until(() => result != null);
  if (!result) throw new Error(`battle did not finish (steps=${steps}, phase=${battle.phase})`);
  return result;
}

function freshParty(classes, level, seedOffset) {
  return classes.map((classId, i) => {
    const c = createCharacter({ name: 'H' + i, raceId: 'emberkin', classId, kitId: representativeKit(classId).id, level });
    return c;
  });
}

const pick6 = (offset) => CLASSES.map(c => c.id).slice(offset % 12, (offset % 12) + 6).length === 6
  ? CLASSES.map(c => c.id).slice(offset % 12, (offset % 12) + 6)
  : [...CLASSES.map(c => c.id).slice(offset % 12), ...CLASSES.map(c => c.id)].slice(0, 6);

