  const prev = new Map([[`${from.x},${from.y}`, null]]);
  const q = [from];
  while (q.length) {
    const cur = q.shift();
    if (cur.x === to.x && cur.y === to.y) break;
    for (const [dx, dy, k] of [[1, 0, 'd'], [-1, 0, 'a'], [0, 1, 's'], [0, -1, 'w']]) {
      const nx = cur.x + dx, ny = cur.y + dy, id = `${nx},${ny}`;
      if (prev.has(id) || !walk(nx, ny)) continue;
      prev.set(id, { from: `${cur.x},${cur.y}`, key: k });
      q.push({ x: nx, y: ny });
    }
  }
  const path = [];
  let cur = `${to.x},${to.y}`;
  while (cur && cur !== `${from.x},${from.y}`) {
    const p = prev.get(cur);
    if (!p) return null;
    path.unshift(p.key);
    cur = p.from;
  }
  return path;
}
for (let i = 0; i < 400; i += 1) {
  const a = await getApp();
  const target = a.encounters.find(e => !e.cleared);
  if (await page.evaluate(() => document.querySelector('.screen.is-active')?.id) === 'screen-battle') break;
  const keys = pathKeys(a.pos, target, a);
  if (!keys?.length) throw new Error('no path');
  await page.keyboard.press(keys[0]);
  await sleep(150);
}
if (await page.evaluate(() => document.querySelector('.screen.is-active')?.id) !== 'screen-battle') throw new Error('battle did not start');
await sleep(1000);

// wait for an ally select phase
await page.waitForFunction(() => window.__warband.battle?.phase === 'select' && window.__warband.battle.getActive()?.side === 'ally', null, { timeout: 30000 });
console.log('✔ ally select phase reached');

// click an enemy card → basic attack should enter target phase and then resolve
const enemyUid = await page.evaluate(() => window.__warband.battle.units.find(u => u.side === 'enemy' && u.alive).uid);
await page.click(`.unit[data-uid="${enemyUid}"]`);
await sleep(700);
const afterClick = await page.evaluate(() => ({ phase: window.__warband.battle.phase, msg: document.getElementById('battle-message').textContent }));
console.log('after enemy click:', JSON.stringify(afterClick));
// resolve the battle with auto
await page.keyboard.press('a');
console.log('✔ battle resolving via auto');
const t0 = Date.now();
let outcome = 'timeout';
while (Date.now() - t0 < 180000) {
  const s = await page.evaluate(() => {
    const v = !!document.getElementById('btn-victory-continue');
    const d = !!document.getElementById('btn-defeat-retry');
    return { v, d, phase: window.__warband.battle?.phase };
  });
  if (s.v) { outcome = 'victory'; break; }
  if (s.d) { outcome = 'defeat'; break; }
  await sleep(500);
}
console.log('✔ battle outcome:', outcome);
if (outcome === 'victory') {
  await page.click('#btn-victory-continue');
  await sleep(700);
  console.log('✔ returned to:', await page.evaluate(() => document.querySelector('.screen.is-active')?.id));
}
console.log('\nerrors:', errors.length ? errors.slice(0, 10) : 'none');
await browser.close();
if (errors.length) process.exitCode = 1;

